const crypto = require('crypto');
const input = $input.first().json;
const headers = input.headers || {};
const body = input.body || input;
const timestamp = String(headers['x-ai-test-timestamp'] || '');
const signature = String(headers['x-ai-test-signature'] || '').replace(/^sha256=/, '');
if (!/^\d+$/.test(timestamp) || Math.abs(Date.now() / 1000 - Number(timestamp)) > 300) throw new Error('expired webhook timestamp');
const canonical = (v) => Array.isArray(v) ? '[' + v.map(canonical).join(',') + ']' : v && typeof v === 'object' ? '{' + Object.keys(v).sort().map(k => JSON.stringify(k) + ':' + canonical(v[k])).join(',') + '}' : JSON.stringify(v);
const raw = input.rawBody || canonical(body);
const expected = crypto.createHmac('sha256', $env.AI_TEST_PLAN_WEBHOOK_SECRET).update(timestamp + '.' + raw).digest('hex');
if (signature.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected))) throw new Error('invalid webhook signature');
for (const field of ['task_id','repository','branch','base_sha','plan','callback_url']) if (body[field] === undefined) throw new Error('missing field: ' + field);
if (!/^[0-9a-f]{40}$/.test(body.base_sha)) throw new Error('base_sha must be a full SHA');
const digest = crypto.createHash('sha256').update(canonical(body.plan)).digest('hex');
return [{ json: { request: body, idempotencyKey: body.task_id + ':' + body.base_sha + ':' + digest } }];
